/**
 * Differentiable Contact Physics Simulator
 * Implements compliant contact model with stiffness, damping, and friction
 * Based on Isaac Sim / MuJoCo contact dynamics
 */

export class ContactSimulator {
  constructor(groundTruthParams = null) {
    // Ground truth parameters (hidden from user initially)
    this.groundTruth = groundTruthParams || {
      stiffness: 5e5,      // N/m
      damping: 0.3,         // damping ratio
      friction: 0.45,       // friction coefficient
      restitution: 0.1      // coefficient of restitution
    };

    // Simulation state
    this.dt = 0.001; // 1ms timestep
    this.gravity = -9.81;

    // Robot state (simplified 1DOF insertion)
    this.position = 0.0;
    this.velocity = 0.0;
    this.mass = 0.5; // kg

    // Connector geometry
    this.connectorDepth = 0.02; // 20mm insertion depth
    this.tolerance = 0.0001; // 0.1mm clearance
  }

  /**
   * Forward simulation with given contact parameters
   * Returns force/torque trace for comparison with real data
   */
  simulate(params, targetTrajectory, steps = 1000) {
    const { stiffness, damping, friction } = params;

    // Reset state
    let pos = 0.0;
    let vel = 0.0;

    const forceTrace = [];
    const positionTrace = [];
    const velocityTrace = [];

    for (let i = 0; i < steps; i++) {
      const t = i * this.dt;

      // Target position from trajectory
      const targetPos = this.interpolateTrajectory(targetTrajectory, t);
      const targetVel = i > 0 ? (targetPos - this.interpolateTrajectory(targetTrajectory, t - this.dt)) / this.dt : 0;

      // Contact detection
      const penetration = Math.max(0, pos - this.connectorDepth);

      // Contact forces (compliant contact model)
      let contactForce = 0;
      if (penetration > 0) {
        // Normal force: F = k * δ + c * δ̇
        const normalForce = stiffness * penetration +
                           (2 * damping * Math.sqrt(stiffness * this.mass)) * vel;

        // Friction force (Coulomb model)
        const frictionForce = friction * normalForce * Math.sign(vel);

        contactForce = -(normalForce + frictionForce);
      }

      // PD controller to follow trajectory
      const kp = 1000;
      const kd = 50;
      const controlForce = kp * (targetPos - pos) + kd * (targetVel - vel);

      // Total force
      const totalForce = controlForce + contactForce + this.mass * this.gravity;

      // Integrate dynamics
      const acc = totalForce / this.mass;
      vel += acc * this.dt;
      pos += vel * this.dt;

      // Store trace data
      forceTrace.push({
        time: t,
        contact: -contactForce,
        control: controlForce,
        total: totalForce
      });
      positionTrace.push({ time: t, position: pos });
      velocityTrace.push({ time: t, velocity: vel });
    }

    return {
      forceTrace,
      positionTrace,
      velocityTrace,
      success: this.checkInsertionSuccess(positionTrace),
      finalPenetration: Math.max(0, positionTrace[positionTrace.length - 1].position - this.connectorDepth)
    };
  }

  /**
   * Generate ground truth data (simulates "real hardware")
   */
  generateGroundTruthData(trajectory, noiseLevel = 0.02) {
    const result = this.simulate(this.groundTruth, trajectory);

    // Add realistic sensor noise
    result.forceTrace = result.forceTrace.map(f => ({
      ...f,
      contact: f.contact + (Math.random() - 0.5) * noiseLevel * Math.abs(f.contact),
      total: f.total + (Math.random() - 0.5) * noiseLevel * Math.abs(f.total)
    }));

    return result;
  }

  /**
   * Compute loss between simulated and ground truth traces
   * Used for optimization objective
   */
  computeLoss(params, groundTruthTrace, trajectory) {
    const simResult = this.simulate(params, trajectory, groundTruthTrace.forceTrace.length);

    // MSE on contact forces
    let forceMSE = 0;
    for (let i = 0; i < groundTruthTrace.forceTrace.length; i++) {
      const diff = simResult.forceTrace[i].contact - groundTruthTrace.forceTrace[i].contact;
      forceMSE += diff * diff;
    }
    forceMSE /= groundTruthTrace.forceTrace.length;

    // Add position tracking error
    let posMSE = 0;
    for (let i = 0; i < groundTruthTrace.positionTrace.length; i++) {
      const diff = simResult.positionTrace[i].position - groundTruthTrace.positionTrace[i].position;
      posMSE += diff * diff;
    }
    posMSE /= groundTruthTrace.positionTrace.length;

    // Combined loss
    return forceMSE * 1.0 + posMSE * 0.1;
  }

  /**
   * Compute gradient of loss w.r.t. parameters (for gradient-based optimization)
   * Uses finite differences for automatic differentiation
   */
  computeGradient(params, groundTruthTrace, trajectory, epsilon = 1e-4) {
    const baseLoss = this.computeLoss(params, groundTruthTrace, trajectory);

    const gradient = {};
    for (const key of ['stiffness', 'damping', 'friction']) {
      const perturbedParams = { ...params };
      perturbedParams[key] += epsilon;
      const perturbedLoss = this.computeLoss(perturbedParams, groundTruthTrace, trajectory);
      gradient[key] = (perturbedLoss - baseLoss) / epsilon;
    }

    return gradient;
  }

  interpolateTrajectory(trajectory, time) {
    // Simple linear interpolation
    for (let i = 0; i < trajectory.length - 1; i++) {
      if (time >= trajectory[i].time && time <= trajectory[i + 1].time) {
        const t = (time - trajectory[i].time) / (trajectory[i + 1].time - trajectory[i].time);
        return trajectory[i].position + t * (trajectory[i + 1].position - trajectory[i].position);
      }
    }
    return trajectory[trajectory.length - 1].position;
  }

  checkInsertionSuccess(positionTrace) {
    const finalPos = positionTrace[positionTrace.length - 1].position;
    return Math.abs(finalPos - this.connectorDepth) < 0.001; // 1mm tolerance
  }

  /**
   * Generate test trajectories for validation
   */
  static generateTestTrajectories() {
    return [
      // Slow insertion
      {
        name: 'Slow Insertion',
        points: [
          { time: 0, position: 0 },
          { time: 1.0, position: 0.025 }
        ]
      },
      // Fast insertion
      {
        name: 'Fast Insertion',
        points: [
          { time: 0, position: 0 },
          { time: 0.3, position: 0.025 }
        ]
      },
      // Two-stage insertion
      {
        name: 'Two-Stage',
        points: [
          { time: 0, position: 0 },
          { time: 0.5, position: 0.01 },
          { time: 0.6, position: 0.01 },
          { time: 1.2, position: 0.025 }
        ]
      },
      // Spiral search
      {
        name: 'Spiral Search',
        points: [
          { time: 0, position: 0 },
          { time: 0.3, position: 0.005 },
          { time: 0.4, position: 0.003 },
          { time: 0.6, position: 0.008 },
          { time: 1.0, position: 0.025 }
        ]
      },
      // Compliance-based
      {
        name: 'Compliance-Based',
        points: [
          { time: 0, position: 0 },
          { time: 0.8, position: 0.015 },
          { time: 1.5, position: 0.025 }
        ]
      }
    ];
  }
}
