import { useEffect, useState } from 'react';
import ContactVisualizer from './components/ContactVisualizer';
import ForceChart from './components/ForceChart';
import ParameterControls from './components/ParameterControls';
import AlgorithmRace from './components/AlgorithmRace';
import ValidationDashboard from './components/ValidationDashboard';
import useSimulationStore from './store/simulationStore';
import './App.css';

function App() {
  const {
    groundTruthTrace,
    userSimResult,
    algorithmProgress,
    simulator,
    trajectory,
    initializeSimulation
  } = useSimulationStore();

  const [selectedView, setSelectedView] = useState('overview');

  useEffect(() => {
    initializeSimulation();
  }, [initializeSimulation]);

  // Generate algorithm simulation results for comparison
  const getAlgorithmResults = () => {
    const results = {};

    if (algorithmProgress.bayesian?.bestParams && simulator && trajectory && groundTruthTrace) {
      results.bayesian = simulator.simulate(
        algorithmProgress.bayesian.bestParams,
        trajectory,
        groundTruthTrace.forceTrace.length
      );
    }

    if (algorithmProgress.cmaes?.bestParams && simulator && trajectory && groundTruthTrace) {
      results.cmaes = simulator.simulate(
        algorithmProgress.cmaes.bestParams,
        trajectory,
        groundTruthTrace.forceTrace.length
      );
    }

    if (algorithmProgress.gradient?.bestParams && simulator && trajectory && groundTruthTrace) {
      results.gradient = simulator.simulate(
        algorithmProgress.gradient.bestParams,
        trajectory,
        groundTruthTrace.forceTrace.length
      );
    }

    return results;
  };

  const algorithmResults = getAlgorithmResults();

  return (
    <div className="app">
      {/* Header */}
      <header className="header">
        <div className="header-content">
          <div className="logo-section">
            <div className="logo-text">DELBY AI</div>
            <div className="tagline">Sensor Data Platform for Autonomous Vehicles</div>
          </div>
          <div className="title-section">
            <h1>IsaacForge Contact Oracle</h1>
            <p>Interactive Sim-to-Real Contact Physics Parameter Identification Arena</p>
          </div>
        </div>
      </header>

      {/* Navigation */}
      <nav className="nav">
        <button
          className={selectedView === 'overview' ? 'active' : ''}
          onClick={() => setSelectedView('overview')}
        >
          📊 Overview
        </button>
        <button
          className={selectedView === 'optimization' ? 'active' : ''}
          onClick={() => setSelectedView('optimization')}
        >
          🏁 Algorithm Race
        </button>
        <button
          className={selectedView === 'validation' ? 'active' : ''}
          onClick={() => setSelectedView('validation')}
        >
          🎯 Validation
        </button>
      </nav>

      {/* Main content */}
      <main className="main-content">
        {selectedView === 'overview' && (
          <div className="grid-layout">
            {/* Left column */}
            <div className="left-column">
              <section className="card">
                <h2>Mission</h2>
                <p>
                  Identify real-world contact physics parameters by matching simulation to observed hardware behavior.
                  Tune stiffness, damping, and friction coefficients to minimize the difference between simulated and
                  real force traces.
                </p>
                <div className="mission-steps">
                  <div className="step">
                    <span className="step-number">1</span>
                    <span>Watch real insertion attempt (left side)</span>
                  </div>
                  <div className="step">
                    <span className="step-number">2</span>
                    <span>Adjust contact parameters manually</span>
                  </div>
                  <div className="step">
                    <span className="step-number">3</span>
                    <span>Or click "Race All" to watch algorithms compete</span>
                  </div>
                  <div className="step">
                    <span className="step-number">4</span>
                    <span>Validate on held-out test cases</span>
                  </div>
                </div>
              </section>

              <section>
                <ParameterControls />
              </section>
            </div>

            {/* Right column */}
            <div className="right-column">
              <section>
                <ContactVisualizer
                  groundTruthTrace={groundTruthTrace}
                  userSimResult={userSimResult}
                  showComparison={true}
                />
              </section>

              <section>
                <ForceChart
                  groundTruthTrace={groundTruthTrace}
                  userSimResult={userSimResult}
                  algorithmResults={algorithmResults}
                />
              </section>
            </div>
          </div>
        )}

        {selectedView === 'optimization' && (
          <div className="single-column-layout">
            <section>
              <AlgorithmRace />
            </section>

            <section style={{ marginTop: '20px' }}>
              <ForceChart
                groundTruthTrace={groundTruthTrace}
                userSimResult={userSimResult}
                algorithmResults={algorithmResults}
              />
            </section>

            <section style={{ marginTop: '20px' }}>
              <ContactVisualizer
                groundTruthTrace={groundTruthTrace}
                userSimResult={userSimResult}
                showComparison={true}
              />
            </section>
          </div>
        )}

        {selectedView === 'validation' && (
          <div className="single-column-layout">
            <section>
              <ValidationDashboard />
            </section>

            <section style={{ marginTop: '20px' }}>
              <div className="info-panel">
                <h3>About Validation Testing</h3>
                <p>
                  The validation phase tests your identified parameters on 5 different insertion trajectories
                  that were NOT used during parameter optimization:
                </p>
                <ul>
                  <li><strong>Slow Insertion:</strong> Gentle, controlled insertion over 1 second</li>
                  <li><strong>Fast Insertion:</strong> Quick insertion in 0.3 seconds</li>
                  <li><strong>Two-Stage:</strong> Partial insertion, pause, then complete</li>
                  <li><strong>Spiral Search:</strong> Search pattern with varying depth</li>
                  <li><strong>Compliance-Based:</strong> Adaptive insertion with force feedback</li>
                </ul>
                <p>
                  This tests the <strong>generalization</strong> of your identified parameters.
                  In real sim-to-real transfer, parameters must work across diverse scenarios, not just the training data.
                </p>
              </div>
            </section>
          </div>
        )}
      </main>

      {/* Footer */}
      <footer className="footer">
        <div className="footer-content">
          <div className="footer-section">
            <h4>Algorithms</h4>
            <div className="algorithm-tag bayesian">Bayesian Optimization</div>
            <div className="algorithm-tag cmaes">CMA-ES</div>
            <div className="algorithm-tag gradient">Gradient Descent</div>
          </div>
          <div className="footer-section">
            <h4>Physics Engine</h4>
            <p>Compliant contact model with:</p>
            <ul>
              <li>Stiffness: 10³ - 10⁷ N/m</li>
              <li>Damping: 0.01 - 1.0</li>
              <li>Friction: 0.1 - 0.9 μ</li>
            </ul>
          </div>
          <div className="footer-section">
            <h4>Technologies</h4>
            <p>React • Three.js • Recharts</p>
            <p>Differentiable Physics</p>
            <p>System Identification</p>
          </div>
        </div>
        <div className="footer-bottom">
          <p>Built by Delby AI • Robotics Competition Agent</p>
          <p>Targeting: Intrinsic AI for Industry Challenge ($180K)</p>
        </div>
      </footer>
    </div>
  );
}

export default App;
