/**
 * Gradient-Based Optimizer with Adam
 * Uses analytic gradients from differentiable contact simulator
 */

export class GradientOptimizer {
  constructor(bounds, simulator, groundTruthTrace, trajectory) {
    this.bounds = bounds;
    this.simulator = simulator;
    this.groundTruthTrace = groundTruthTrace;
    this.trajectory = trajectory;

    // Adam optimizer parameters
    this.learningRate = 0.01;
    this.beta1 = 0.9;
    this.beta2 = 0.999;
    this.epsilon = 1e-8;

    // Current parameters (initialized at center of bounds, in log-space for stiffness)
    this.params = this.initializeParams();

    // Adam state
    this.m = { stiffness: 0, damping: 0, friction: 0 }; // first moment
    this.v = { stiffness: 0, damping: 0, friction: 0 }; // second moment
    this.t = 0; // timestep

    // Best found
    this.bestParams = { ...this.params };
    this.bestLoss = Infinity;

    // History
    this.history = [];
  }

  /**
   * Initialize parameters at center of search space
   */
  initializeParams() {
    const params = {};
    for (const key in this.bounds) {
      const [min, max] = this.bounds[key];
      if (key === 'stiffness') {
        // Log-space for stiffness
        const logMin = Math.log10(min);
        const logMax = Math.log10(max);
        params[key] = Math.pow(10, (logMin + logMax) / 2);
      } else {
        params[key] = (min + max) / 2;
      }
    }
    return params;
  }

  /**
   * Run one step of gradient-based optimization
   */
  step() {
    this.t++;

    // Compute loss and gradient
    const loss = this.simulator.computeLoss(this.params, this.groundTruthTrace, this.trajectory);
    const gradient = this.simulator.computeGradient(this.params, this.groundTruthTrace, this.trajectory);

    // Transform gradient for log-space stiffness
    const transformedGradient = { ...gradient };
    transformedGradient.stiffness = gradient.stiffness * this.params.stiffness * Math.LN10;

    // Adam update
    const updates = {};
    for (const key in this.params) {
      // Update biased first moment estimate
      this.m[key] = this.beta1 * this.m[key] + (1 - this.beta1) * transformedGradient[key];

      // Update biased second raw moment estimate
      this.v[key] = this.beta2 * this.v[key] + (1 - this.beta2) * transformedGradient[key] * transformedGradient[key];

      // Compute bias-corrected moment estimates
      const mHat = this.m[key] / (1 - Math.pow(this.beta1, this.t));
      const vHat = this.v[key] / (1 - Math.pow(this.beta2, this.t));

      // Compute update
      updates[key] = -this.learningRate * mHat / (Math.sqrt(vHat) + this.epsilon);
    }

    // Apply updates with log-space handling
    for (const key in this.params) {
      if (key === 'stiffness') {
        // Update in log-space
        const logVal = Math.log10(this.params[key]);
        const newLogVal = logVal + updates[key] / (this.params[key] * Math.LN10);
        this.params[key] = Math.pow(10, newLogVal);
      } else {
        this.params[key] += updates[key];
      }

      // Project back to bounds
      const [min, max] = this.bounds[key];
      this.params[key] = Math.max(min, Math.min(max, this.params[key]));
    }

    // Track best
    if (loss < this.bestLoss) {
      this.bestLoss = loss;
      this.bestParams = { ...this.params };
    }

    // Record history
    this.history.push({
      iteration: this.t,
      params: { ...this.params },
      loss,
      gradient: { ...gradient },
      gradientNorm: Math.sqrt(
        Object.values(transformedGradient).reduce((sum, g) => sum + g * g, 0)
      )
    });

    return {
      params: { ...this.params },
      loss,
      gradient: transformedGradient,
      gradientNorm: this.history[this.history.length - 1].gradientNorm
    };
  }

  /**
   * Adaptive learning rate based on gradient history
   */
  adaptLearningRate() {
    if (this.history.length < 5) return;

    const recentGrads = this.history.slice(-5).map(h => h.gradientNorm);
    const recentLosses = this.history.slice(-5).map(h => h.loss);

    // If gradient norm is increasing but loss isn't decreasing, reduce learning rate
    const gradIncreasing = recentGrads[recentGrads.length - 1] > recentGrads[0];
    const lossNotDecreasing = recentLosses[recentLosses.length - 1] >= recentLosses[0];

    if (gradIncreasing && lossNotDecreasing) {
      this.learningRate *= 0.5;
    }

    // If loss is decreasing consistently, can try increasing learning rate
    const lossDecreasing = recentLosses.every((l, i) =>
      i === 0 || l <= recentLosses[i - 1]
    );

    if (lossDecreasing && this.learningRate < 0.1) {
      this.learningRate *= 1.05;
    }
  }

  /**
   * Line search to find optimal step size
   */
  lineSearch(direction, maxSteps = 10, alpha = 0.3, beta = 0.8) {
    const currentLoss = this.simulator.computeLoss(this.params, this.groundTruthTrace, this.trajectory);

    let stepSize = 1.0;
    for (let i = 0; i < maxSteps; i++) {
      const testParams = {};
      for (const key in this.params) {
        testParams[key] = this.params[key] + stepSize * direction[key];

        // Project to bounds
        const [min, max] = this.bounds[key];
        testParams[key] = Math.max(min, Math.min(max, testParams[key]));
      }

      const testLoss = this.simulator.computeLoss(testParams, this.groundTruthTrace, this.trajectory);

      // Armijo condition
      const directionNorm = Math.sqrt(
        Object.values(direction).reduce((sum, d) => sum + d * d, 0)
      );

      if (testLoss <= currentLoss - alpha * stepSize * directionNorm * directionNorm) {
        return stepSize;
      }

      stepSize *= beta;
    }

    return stepSize;
  }

  /**
   * Get optimization progress
   */
  getProgress() {
    return {
      iteration: this.t,
      params: this.params,
      bestParams: this.bestParams,
      bestLoss: this.bestLoss,
      currentLoss: this.history.length > 0 ? this.history[this.history.length - 1].loss : Infinity,
      gradientNorm: this.history.length > 0 ? this.history[this.history.length - 1].gradientNorm : 0,
      learningRate: this.learningRate,
      history: this.history
    };
  }

  reset() {
    this.params = this.initializeParams();
    this.m = { stiffness: 0, damping: 0, friction: 0 };
    this.v = { stiffness: 0, damping: 0, friction: 0 };
    this.t = 0;
    this.bestParams = { ...this.params };
    this.bestLoss = Infinity;
    this.history = [];
    this.learningRate = 0.01;
  }
}
