/**
 * CMA-ES (Covariance Matrix Adaptation Evolution Strategy)
 * Population-based black-box optimization for contact parameter identification
 */

import { create, all } from 'mathjs';
const math = create(all);

export class CMAESOptimizer {
  constructor(bounds, simulator, groundTruthTrace, trajectory) {
    this.bounds = bounds;
    this.simulator = simulator;
    this.groundTruthTrace = groundTruthTrace;
    this.trajectory = trajectory;

    // CMA-ES parameters
    this.dim = 3; // stiffness, damping, friction
    this.lambda = 8; // population size
    this.mu = Math.floor(this.lambda / 2); // number of parents

    // Recombination weights
    this.weights = Array(this.mu).fill(0).map((_, i) =>
      Math.log(this.mu + 0.5) - Math.log(i + 1)
    );
    const sumWeights = this.weights.reduce((a, b) => a + b, 0);
    this.weights = this.weights.map(w => w / sumWeights);
    this.mueff = 1 / this.weights.reduce((sum, w) => sum + w * w, 0);

    // Adaptation parameters
    this.cc = (4 + this.mueff / this.dim) / (this.dim + 4 + 2 * this.mueff / this.dim);
    this.cs = (this.mueff + 2) / (this.dim + this.mueff + 5);
    this.c1 = 2 / ((this.dim + 1.3) * (this.dim + 1.3) + this.mueff);
    this.cmu = Math.min(1 - this.c1, 2 * (this.mueff - 2 + 1 / this.mueff) / ((this.dim + 2) * (this.dim + 2) + this.mueff));
    this.damps = 1 + 2 * Math.max(0, Math.sqrt((this.mueff - 1) / (this.dim + 1)) - 1) + this.cs;

    // Initialize mean (center of search space in normalized coordinates)
    this.mean = Array(this.dim).fill(0.5);

    // Covariance matrix and related
    this.sigma = 0.3; // step size
    this.pc = Array(this.dim).fill(0); // evolution path for C
    this.ps = Array(this.dim).fill(0); // evolution path for sigma
    this.C = math.identity(this.dim).valueOf(); // covariance matrix
    this.B = math.identity(this.dim).valueOf(); // eigenvectors
    this.D = Array(this.dim).fill(1); // eigenvalues (square roots)

    // Best found
    this.bestParams = null;
    this.bestLoss = Infinity;
    this.generation = 0;

    // Current population
    this.population = [];
  }

  /**
   * Run one generation of CMA-ES
   */
  step() {
    // Generate population
    this.population = [];
    const offspring = [];

    for (let i = 0; i < this.lambda; i++) {
      // Sample from N(0, I)
      const z = Array(this.dim).fill(0).map(() => this.randn());

      // Transform: y = B * D * z
      const y = this.transformSample(z);

      // Add to mean: x = mean + sigma * y
      const xNorm = this.mean.map((m, j) => m + this.sigma * y[j]);

      // Denormalize to actual parameter space
      const params = this.denormalizeParams(xNorm);

      // Evaluate
      const loss = this.simulator.computeLoss(params, this.groundTruthTrace, this.trajectory);

      offspring.push({ params, paramsNorm: xNorm, z, loss });

      if (loss < this.bestLoss) {
        this.bestLoss = loss;
        this.bestParams = { ...params };
      }
    }

    // Sort by fitness
    offspring.sort((a, b) => a.loss - b.loss);
    this.population = offspring;

    // Recombination: compute weighted mean
    const oldMean = [...this.mean];
    this.mean = Array(this.dim).fill(0);

    for (let i = 0; i < this.mu; i++) {
      for (let j = 0; j < this.dim; j++) {
        this.mean[j] += this.weights[i] * offspring[i].paramsNorm[j];
      }
    }

    // Update evolution paths
    const meanShift = this.mean.map((m, i) => (m - oldMean[i]) / this.sigma);

    // ps update (for step-size control)
    const Cinvsqrt = this.computeInvSqrtC();
    const CinvsqrtMeanShift = math.multiply(Cinvsqrt, meanShift);

    for (let i = 0; i < this.dim; i++) {
      this.ps[i] = (1 - this.cs) * this.ps[i] +
                   Math.sqrt(this.cs * (2 - this.cs) * this.mueff) * CinvsqrtMeanShift[i];
    }

    // pc update (for covariance matrix)
    const hsig = this.computeHsig();
    const factor = hsig * Math.sqrt(this.cc * (2 - this.cc) * this.mueff);

    for (let i = 0; i < this.dim; i++) {
      this.pc[i] = (1 - this.cc) * this.pc[i] + factor * meanShift[i];
    }

    // Update covariance matrix
    this.updateCovarianceMatrix(offspring, hsig);

    // Update step size
    const psNorm = Math.sqrt(this.ps.reduce((sum, p) => sum + p * p, 0));
    const expectedNorm = Math.sqrt(this.dim) * (1 - 1 / (4 * this.dim) + 1 / (21 * this.dim * this.dim));
    this.sigma *= Math.exp((this.cs / this.damps) * (psNorm / expectedNorm - 1));

    // Eigendecomposition of C
    this.updateEigendecomposition();

    this.generation++;

    return {
      params: this.bestParams,
      loss: this.bestLoss,
      generation: this.generation,
      sigma: this.sigma,
      population: offspring.slice(0, this.mu).map(o => ({ params: o.params, loss: o.loss }))
    };
  }

  /**
   * Transform sample using B * D
   */
  transformSample(z) {
    const y = Array(this.dim).fill(0);
    for (let i = 0; i < this.dim; i++) {
      for (let j = 0; j < this.dim; j++) {
        y[i] += this.B[i][j] * this.D[j] * z[j];
      }
    }
    return y;
  }

  /**
   * Compute C^(-1/2) using eigendecomposition
   */
  computeInvSqrtC() {
    const Dinv = this.D.map(d => 1 / d);
    const result = Array(this.dim).fill(0).map(() => Array(this.dim).fill(0));

    for (let i = 0; i < this.dim; i++) {
      for (let j = 0; j < this.dim; j++) {
        for (let k = 0; k < this.dim; k++) {
          result[i][j] += this.B[i][k] * Dinv[k] * this.B[j][k];
        }
      }
    }

    return result;
  }

  /**
   * Compute hsig indicator
   */
  computeHsig() {
    const psNorm = Math.sqrt(this.ps.reduce((sum, p) => sum + p * p, 0));
    const expectedNorm = Math.sqrt(this.dim) * (1 - 1 / (4 * this.dim) + 1 / (21 * this.dim * this.dim));
    const threshold = (1.4 + 2 / (this.dim + 1)) * expectedNorm;
    return psNorm < threshold ? 1 : 0;
  }

  /**
   * Update covariance matrix
   */
  updateCovarianceMatrix(offspring, hsig) {
    // Rank-one update
    const pcOuter = math.multiply(math.matrix([this.pc]), math.matrix([this.pc]).transpose()).valueOf();

    // Rank-mu update
    const artmp = offspring.slice(0, this.mu).map(o => {
      return o.paramsNorm.map((x, i) => (x - this.mean[i]) / this.sigma);
    });

    let rankMuUpdate = Array(this.dim).fill(0).map(() => Array(this.dim).fill(0));
    for (let i = 0; i < this.mu; i++) {
      const outer = math.multiply(math.matrix([artmp[i]]), math.matrix([artmp[i]]).transpose()).valueOf();
      for (let j = 0; j < this.dim; j++) {
        for (let k = 0; k < this.dim; k++) {
          rankMuUpdate[j][k] += this.weights[i] * outer[j][k];
        }
      }
    }

    // Combine updates
    for (let i = 0; i < this.dim; i++) {
      for (let j = 0; j < this.dim; j++) {
        this.C[i][j] = (1 - this.c1 - this.cmu) * this.C[i][j] +
                       this.c1 * (pcOuter[i][j] + (1 - hsig) * this.cc * (2 - this.cc) * this.C[i][j]) +
                       this.cmu * rankMuUpdate[i][j];
      }
    }

    // Ensure symmetry
    for (let i = 0; i < this.dim; i++) {
      for (let j = i + 1; j < this.dim; j++) {
        this.C[i][j] = this.C[j][i] = (this.C[i][j] + this.C[j][i]) / 2;
      }
    }
  }

  /**
   * Update eigendecomposition of covariance matrix
   */
  updateEigendecomposition() {
    try {
      const eigen = math.eigs(this.C);
      this.B = eigen.vectors.valueOf();
      this.D = eigen.values.map(v => Math.sqrt(Math.abs(v.re || v)));
    } catch (e) {
      // Keep previous decomposition if numerical issues
      console.warn('Eigendecomposition failed, keeping previous');
    }
  }

  /**
   * Denormalize parameters from [0,1] to actual bounds
   */
  denormalizeParams(paramsNorm) {
    const params = {};
    const keys = Object.keys(this.bounds);

    paramsNorm.forEach((val, i) => {
      const key = keys[i];
      const [min, max] = this.bounds[key];

      // Clamp to [0, 1]
      const clamped = Math.max(0, Math.min(1, val));

      if (key === 'stiffness') {
        // Log-scale for stiffness
        const logMin = Math.log10(min);
        const logMax = Math.log10(max);
        params[key] = Math.pow(10, logMin + clamped * (logMax - logMin));
      } else {
        params[key] = min + clamped * (max - min);
      }
    });

    return params;
  }

  /**
   * Sample from standard normal distribution (Box-Muller)
   */
  randn() {
    const u1 = Math.random();
    const u2 = Math.random();
    return Math.sqrt(-2 * Math.log(u1)) * Math.cos(2 * Math.PI * u2);
  }

  /**
   * Get optimization progress
   */
  getProgress() {
    return {
      generation: this.generation,
      bestParams: this.bestParams,
      bestLoss: this.bestLoss,
      sigma: this.sigma,
      population: this.population.slice(0, this.mu)
    };
  }

  reset() {
    this.mean = Array(this.dim).fill(0.5);
    this.sigma = 0.3;
    this.pc = Array(this.dim).fill(0);
    this.ps = Array(this.dim).fill(0);
    this.C = math.identity(this.dim).valueOf();
    this.B = math.identity(this.dim).valueOf();
    this.D = Array(this.dim).fill(1);
    this.bestParams = null;
    this.bestLoss = Infinity;
    this.generation = 0;
    this.population = [];
  }
}
