/**
 * Bayesian Optimization for Contact Parameter Identification
 * Uses Gaussian Process surrogate model + Expected Improvement acquisition
 */

import { create, all } from 'mathjs';
const math = create(all);

export class BayesianOptimizer {
  constructor(bounds, simulator, groundTruthTrace, trajectory) {
    this.bounds = bounds; // { stiffness: [min, max], damping: [min, max], friction: [min, max] }
    this.simulator = simulator;
    this.groundTruthTrace = groundTruthTrace;
    this.trajectory = trajectory;

    // Observation history
    this.observations = []; // { params, loss }

    // GP hyperparameters
    this.lengthScale = 0.3;
    this.signalVariance = 1.0;
    this.noiseVariance = 1e-6;

    // Best found
    this.bestParams = null;
    this.bestLoss = Infinity;

    // Iteration counter
    this.iteration = 0;
  }

  /**
   * Run one iteration of Bayesian Optimization
   */
  step() {
    // Random initialization for first 5 samples
    if (this.observations.length < 5) {
      const params = this.sampleRandom();
      const loss = this.simulator.computeLoss(params, this.groundTruthTrace, this.trajectory);

      this.observations.push({ params, loss });

      if (loss < this.bestLoss) {
        this.bestLoss = loss;
        this.bestParams = { ...params };
      }

      this.iteration++;
      return { params, loss, acquisition: null };
    }

    // Use Expected Improvement to select next point
    const candidate = this.optimizeAcquisition();
    const loss = this.simulator.computeLoss(candidate, this.groundTruthTrace, this.trajectory);

    this.observations.push({ params: candidate, loss });

    if (loss < this.bestLoss) {
      this.bestLoss = loss;
      this.bestParams = { ...candidate };
    }

    this.iteration++;

    return {
      params: candidate,
      loss,
      acquisition: this.expectedImprovement(candidate)
    };
  }

  /**
   * Optimize Expected Improvement acquisition function
   */
  optimizeAcquisition(numCandidates = 50) {
    let bestCandidate = null;
    let bestEI = -Infinity;

    for (let i = 0; i < numCandidates; i++) {
      const candidate = this.sampleRandom();
      const ei = this.expectedImprovement(candidate);

      if (ei > bestEI) {
        bestEI = ei;
        bestCandidate = candidate;
      }
    }

    return bestCandidate;
  }

  /**
   * Expected Improvement acquisition function
   */
  expectedImprovement(params) {
    const { mean, std } = this.gpPredict(params);

    if (std < 1e-8) return 0;

    const improvement = this.bestLoss - mean;
    const z = improvement / std;

    // EI = improvement * Φ(z) + std * φ(z)
    const phi = this.normalPDF(z);
    const Phi = this.normalCDF(z);

    return improvement * Phi + std * phi;
  }

  /**
   * Gaussian Process prediction
   */
  gpPredict(params) {
    if (this.observations.length === 0) {
      return { mean: 0, std: this.signalVariance };
    }

    // Kernel matrix K(X, X)
    const n = this.observations.length;
    const K = this.computeKernelMatrix(this.observations);

    // Add noise to diagonal
    for (let i = 0; i < n; i++) {
      K[i][i] += this.noiseVariance;
    }

    // Kernel vector k(x, X)
    const k = this.observations.map(obs =>
      this.rbfKernel(params, obs.params)
    );

    // Targets
    const y = this.observations.map(obs => obs.loss);

    // Compute K^-1 * y
    try {
      const Kinv = math.inv(K);
      const KinvY = math.multiply(Kinv, y);

      // Mean prediction: k^T * K^-1 * y
      const mean = math.dot(k, KinvY);

      // Variance prediction: k(x,x) - k^T * K^-1 * k
      const kxx = this.signalVariance;
      const KinvK = math.multiply(Kinv, k);
      const variance = kxx - math.dot(k, KinvK);
      const std = Math.sqrt(Math.max(0, variance));

      return { mean, std };
    } catch (e) {
      // Numerical instability - return prior
      return { mean: 0, std: this.signalVariance };
    }
  }

  /**
   * Compute kernel matrix for observations
   */
  computeKernelMatrix(observations) {
    const n = observations.length;
    const K = Array(n).fill(0).map(() => Array(n).fill(0));

    for (let i = 0; i < n; i++) {
      for (let j = 0; j < n; j++) {
        K[i][j] = this.rbfKernel(observations[i].params, observations[j].params);
      }
    }

    return K;
  }

  /**
   * RBF (Squared Exponential) kernel
   */
  rbfKernel(params1, params2) {
    const normalized1 = this.normalizeParams(params1);
    const normalized2 = this.normalizeParams(params2);

    let distSq = 0;
    for (const key in normalized1) {
      const diff = normalized1[key] - normalized2[key];
      distSq += diff * diff;
    }

    return this.signalVariance * Math.exp(-distSq / (2 * this.lengthScale * this.lengthScale));
  }

  /**
   * Normalize parameters to [0, 1]
   */
  normalizeParams(params) {
    const normalized = {};
    for (const key in params) {
      const [min, max] = this.bounds[key];
      normalized[key] = (params[key] - min) / (max - min);
    }
    return normalized;
  }

  /**
   * Sample random parameters from bounds
   */
  sampleRandom() {
    const params = {};
    for (const key in this.bounds) {
      const [min, max] = this.bounds[key];
      if (key === 'stiffness') {
        // Log-uniform sampling for stiffness
        const logMin = Math.log10(min);
        const logMax = Math.log10(max);
        params[key] = Math.pow(10, logMin + Math.random() * (logMax - logMin));
      } else {
        params[key] = min + Math.random() * (max - min);
      }
    }
    return params;
  }

  /**
   * Standard normal PDF
   */
  normalPDF(x) {
    return Math.exp(-0.5 * x * x) / Math.sqrt(2 * Math.PI);
  }

  /**
   * Standard normal CDF (approximation)
   */
  normalCDF(x) {
    const t = 1 / (1 + 0.2316419 * Math.abs(x));
    const d = 0.3989423 * Math.exp(-x * x / 2);
    const p = d * t * (0.3193815 + t * (-0.3565638 + t * (1.781478 + t * (-1.821256 + t * 1.330274))));
    return x > 0 ? 1 - p : p;
  }

  /**
   * Get optimization progress
   */
  getProgress() {
    return {
      iteration: this.iteration,
      bestParams: this.bestParams,
      bestLoss: this.bestLoss,
      observations: this.observations
    };
  }

  reset() {
    this.observations = [];
    this.bestParams = null;
    this.bestLoss = Infinity;
    this.iteration = 0;
  }
}
