import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer } from 'recharts';

/**
 * Real-time force trace comparison chart
 */
export default function ForceChart({ groundTruthTrace, userSimResult, algorithmResults = {} }) {
  if (!groundTruthTrace) return null;

  // Prepare data for chart
  const chartData = groundTruthTrace.forceTrace.map((point, idx) => {
    const dataPoint = {
      time: point.time,
      real: point.contact,
      user: userSimResult ? userSimResult.forceTrace[idx]?.contact || 0 : 0
    };

    // Add algorithm results if available
    if (algorithmResults.bayesian) {
      dataPoint.bayesian = algorithmResults.bayesian.forceTrace[idx]?.contact || 0;
    }
    if (algorithmResults.cmaes) {
      dataPoint.cmaes = algorithmResults.cmaes.forceTrace[idx]?.contact || 0;
    }
    if (algorithmResults.gradient) {
      dataPoint.gradient = algorithmResults.gradient.forceTrace[idx]?.contact || 0;
    }

    return dataPoint;
  });

  return (
    <div style={{
      background: '#0f0f0f',
      borderRadius: '8px',
      padding: '20px',
      border: '1px solid #222'
    }}>
      <h3 style={{ margin: '0 0 16px 0', fontSize: '16px', color: '#fff' }}>
        Contact Force Traces
      </h3>

      <ResponsiveContainer width="100%" height={300}>
        <LineChart data={chartData}>
          <CartesianGrid strokeDasharray="3 3" stroke="#222" />
          <XAxis
            dataKey="time"
            stroke="#666"
            label={{ value: 'Time (s)', position: 'insideBottom', offset: -5, fill: '#888' }}
          />
          <YAxis
            stroke="#666"
            label={{ value: 'Force (N)', angle: -90, position: 'insideLeft', fill: '#888' }}
          />
          <Tooltip
            contentStyle={{
              background: '#1a1a1a',
              border: '1px solid #333',
              borderRadius: '4px',
              color: '#fff'
            }}
            formatter={(value) => value.toFixed(2) + ' N'}
          />
          <Legend
            wrapperStyle={{ color: '#888' }}
            iconType="line"
          />

          <Line
            type="monotone"
            dataKey="real"
            stroke="#4488ff"
            strokeWidth={2}
            dot={false}
            name="Real Hardware"
          />

          <Line
            type="monotone"
            dataKey="user"
            stroke="#ff8844"
            strokeWidth={2}
            dot={false}
            strokeDasharray="5 5"
            name="Your Params"
          />

          {algorithmResults.bayesian && (
            <Line
              type="monotone"
              dataKey="bayesian"
              stroke="#44ff88"
              strokeWidth={1.5}
              dot={false}
              name="Bayesian Opt"
            />
          )}

          {algorithmResults.cmaes && (
            <Line
              type="monotone"
              dataKey="cmaes"
              stroke="#ff44ff"
              strokeWidth={1.5}
              dot={false}
              name="CMA-ES"
            />
          )}

          {algorithmResults.gradient && (
            <Line
              type="monotone"
              dataKey="gradient"
              stroke="#ffff44"
              strokeWidth={1.5}
              dot={false}
              name="Gradient"
            />
          )}
        </LineChart>
      </ResponsiveContainer>

      {/* Residual metrics */}
      <div style={{
        marginTop: '16px',
        display: 'grid',
        gridTemplateColumns: 'repeat(auto-fit, minmax(150px, 1fr))',
        gap: '12px'
      }}>
        {Object.entries({
          'Your Params': computeRMSE(groundTruthTrace.forceTrace, userSimResult?.forceTrace),
          'Bayesian': computeRMSE(groundTruthTrace.forceTrace, algorithmResults.bayesian?.forceTrace),
          'CMA-ES': computeRMSE(groundTruthTrace.forceTrace, algorithmResults.cmaes?.forceTrace),
          'Gradient': computeRMSE(groundTruthTrace.forceTrace, algorithmResults.gradient?.forceTrace)
        }).map(([name, rmse]) => {
          if (rmse === null) return null;
          return (
            <div
              key={name}
              style={{
                background: '#1a1a1a',
                padding: '12px',
                borderRadius: '6px',
                border: '1px solid #222'
              }}
            >
              <div style={{ fontSize: '11px', color: '#888', marginBottom: '4px' }}>
                {name} RMSE
              </div>
              <div style={{ fontSize: '18px', color: rmse < 5 ? '#44ff88' : rmse < 15 ? '#ff8844' : '#ff4444', fontWeight: 'bold' }}>
                {rmse.toFixed(2)} N
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

/**
 * Compute Root Mean Square Error between traces
 */
function computeRMSE(realTrace, simTrace) {
  if (!realTrace || !simTrace) return null;

  let sumSqError = 0;
  const n = Math.min(realTrace.length, simTrace.length);

  for (let i = 0; i < n; i++) {
    const error = realTrace[i].contact - simTrace[i].contact;
    sumSqError += error * error;
  }

  return Math.sqrt(sumSqError / n);
}
