import { useState, useEffect } from 'react';
import useSimulationStore from '../store/simulationStore';

/**
 * Interactive parameter control sliders
 */
export default function ParameterControls() {
  const {
    userParams,
    setUserParams,
    bounds,
    groundTruthParams,
    metrics,
    selectedAlgorithm,
    algorithmProgress
  } = useSimulationStore();

  const [showGroundTruth, setShowGroundTruth] = useState(false);

  // Convert stiffness to log scale for better control
  const stiffnessToSlider = (stiffness) => {
    const [min, max] = bounds.stiffness;
    const logMin = Math.log10(min);
    const logMax = Math.log10(max);
    const logVal = Math.log10(stiffness);
    return ((logVal - logMin) / (logMax - logMin)) * 100;
  };

  const sliderToStiffness = (slider) => {
    const [min, max] = bounds.stiffness;
    const logMin = Math.log10(min);
    const logMax = Math.log10(max);
    return Math.pow(10, logMin + (slider / 100) * (logMax - logMin));
  };

  const handleStiffnessChange = (e) => {
    const slider = parseFloat(e.target.value);
    const stiffness = sliderToStiffness(slider);
    setUserParams({ ...userParams, stiffness });
  };

  const handleDampingChange = (e) => {
    setUserParams({ ...userParams, damping: parseFloat(e.target.value) });
  };

  const handleFrictionChange = (e) => {
    setUserParams({ ...userParams, friction: parseFloat(e.target.value) });
  };

  // Get comparison params based on selected algorithm
  const getComparisonParams = () => {
    if (selectedAlgorithm === 'manual') return null;

    const progress = algorithmProgress[selectedAlgorithm];
    return progress?.bestParams || null;
  };

  const comparisonParams = getComparisonParams();

  return (
    <div style={{
      background: '#0f0f0f',
      borderRadius: '8px',
      padding: '20px',
      border: '1px solid #222'
    }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '20px' }}>
        <h3 style={{ margin: 0, fontSize: '16px', color: '#fff' }}>
          Contact Parameters
        </h3>
        <button
          onClick={() => setShowGroundTruth(!showGroundTruth)}
          style={{
            background: showGroundTruth ? '#ff4444' : '#333',
            border: 'none',
            borderRadius: '4px',
            padding: '6px 12px',
            color: '#fff',
            fontSize: '11px',
            cursor: 'pointer',
            transition: 'all 0.2s'
          }}
        >
          {showGroundTruth ? '🙈 Hide Truth' : '👁️ Reveal Truth'}
        </button>
      </div>

      {/* Loss metric */}
      <div style={{
        background: '#1a1a1a',
        padding: '12px',
        borderRadius: '6px',
        marginBottom: '20px',
        border: '1px solid #222'
      }}>
        <div style={{ fontSize: '11px', color: '#888', marginBottom: '4px' }}>
          Parameter Error (MSE)
        </div>
        <div style={{ fontSize: '24px', color: getLossColor(metrics.userLoss), fontWeight: 'bold' }}>
          {metrics.userLoss.toFixed(3)}
        </div>
        {comparisonParams && (
          <div style={{ fontSize: '11px', color: '#666', marginTop: '4px' }}>
            {selectedAlgorithm}: {metrics[`${selectedAlgorithm}Loss`]?.toFixed(3) || 'N/A'}
          </div>
        )}
      </div>

      {/* Stiffness slider */}
      <ParameterSlider
        label="Contact Stiffness"
        unit="N/m"
        value={userParams.stiffness}
        displayValue={formatStiffness(userParams.stiffness)}
        min={0}
        max={100}
        step={0.1}
        sliderValue={stiffnessToSlider(userParams.stiffness)}
        onChange={handleStiffnessChange}
        groundTruthValue={showGroundTruth && groundTruthParams ? stiffnessToSlider(groundTruthParams.stiffness) : null}
        formatGroundTruth={(v) => formatStiffness(sliderToStiffness(v))}
        comparisonValue={comparisonParams ? stiffnessToSlider(comparisonParams.stiffness) : null}
      />

      {/* Damping slider */}
      <ParameterSlider
        label="Damping Ratio"
        unit=""
        value={userParams.damping}
        displayValue={userParams.damping.toFixed(3)}
        min={bounds.damping[0]}
        max={bounds.damping[1]}
        step={0.001}
        sliderValue={userParams.damping}
        onChange={handleDampingChange}
        groundTruthValue={showGroundTruth ? groundTruthParams?.damping : null}
        formatGroundTruth={(v) => v.toFixed(3)}
        comparisonValue={comparisonParams?.damping}
      />

      {/* Friction slider */}
      <ParameterSlider
        label="Friction Coefficient"
        unit=""
        value={userParams.friction}
        displayValue={userParams.friction.toFixed(3)}
        min={bounds.friction[0]}
        max={bounds.friction[1]}
        step={0.001}
        sliderValue={userParams.friction}
        onChange={handleFrictionChange}
        groundTruthValue={showGroundTruth ? groundTruthParams?.friction : null}
        formatGroundTruth={(v) => v.toFixed(3)}
        comparisonValue={comparisonParams?.friction}
      />

      {/* Info panel */}
      <div style={{
        marginTop: '20px',
        padding: '12px',
        background: '#1a1a1a',
        borderRadius: '6px',
        border: '1px solid #222',
        fontSize: '11px',
        color: '#888'
      }}>
        <div style={{ marginBottom: '8px', color: '#aaa' }}>
          <strong>Goal:</strong> Match your simulation to the real hardware by tuning contact parameters
        </div>
        <div>
          Lower error = better match. Use sliders or click "Auto-Optimize" to let algorithms race!
        </div>
      </div>
    </div>
  );
}

/**
 * Individual parameter slider component
 */
function ParameterSlider({
  label,
  unit,
  value,
  displayValue,
  min,
  max,
  step,
  sliderValue,
  onChange,
  groundTruthValue,
  formatGroundTruth,
  comparisonValue
}) {
  return (
    <div style={{ marginBottom: '20px' }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '8px' }}>
        <label style={{ fontSize: '13px', color: '#aaa' }}>
          {label}
        </label>
        <div style={{ display: 'flex', gap: '8px', alignItems: 'center' }}>
          <span style={{ fontSize: '14px', color: '#fff', fontFamily: 'monospace' }}>
            {displayValue} {unit}
          </span>
          {groundTruthValue !== null && (
            <span style={{ fontSize: '11px', color: '#44ff88', fontFamily: 'monospace' }}>
              (truth: {formatGroundTruth(groundTruthValue)})
            </span>
          )}
        </div>
      </div>

      <div style={{ position: 'relative' }}>
        <input
          type="range"
          min={min}
          max={max}
          step={step}
          value={sliderValue}
          onChange={onChange}
          style={{
            width: '100%',
            height: '6px',
            borderRadius: '3px',
            outline: 'none',
            background: `linear-gradient(to right, #4488ff 0%, #4488ff ${((sliderValue - min) / (max - min)) * 100}%, #333 ${((sliderValue - min) / (max - min)) * 100}%, #333 100%)`,
            WebkitAppearance: 'none',
            appearance: 'none',
            cursor: 'pointer'
          }}
        />

        {/* Ground truth marker */}
        {groundTruthValue !== null && (() => {
          const gtPosition = ((groundTruthValue - min) / (max - min)) * 100;
          return (
            <div
              style={{
                position: 'absolute',
                left: `${gtPosition}%`,
                top: '-2px',
                width: '2px',
                height: '10px',
                background: '#44ff88',
                boxShadow: '0 0 8px #44ff88'
              }}
            />
          );
        })()}

        {/* Comparison marker */}
        {comparisonValue !== null && (() => {
          const compPosition = ((comparisonValue - min) / (max - min)) * 100;
          return (
            <div
              style={{
                position: 'absolute',
                left: `${compPosition}%`,
                top: '-2px',
                width: '2px',
                height: '10px',
                background: '#ff44ff',
                boxShadow: '0 0 8px #ff44ff'
              }}
            />
          );
        })()}
      </div>
    </div>
  );
}

function formatStiffness(val) {
  if (val >= 1e6) return `${(val / 1e6).toFixed(2)}M`;
  if (val >= 1e3) return `${(val / 1e3).toFixed(1)}k`;
  return val.toFixed(0);
}

function getLossColor(loss) {
  if (loss < 1) return '#44ff88';
  if (loss < 10) return '#88ff44';
  if (loss < 50) return '#ffff44';
  if (loss < 200) return '#ff8844';
  return '#ff4444';
}
