import { useState, useEffect } from 'react';
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer } from 'recharts';
import useSimulationStore from '../store/simulationStore';

/**
 * Algorithm racing dashboard - visualize optimization progress
 */
export default function AlgorithmRace() {
  const {
    optimizationRunning,
    autoOptimizeAlgorithm,
    startOptimization,
    stopOptimization,
    stepOptimization,
    resetAllOptimizers,
    algorithmProgress,
    metrics,
    groundTruthParams
  } = useSimulationStore();

  const [convergenceData, setConvergenceData] = useState([]);
  const [showGroundTruth, setShowGroundTruth] = useState(false);

  // Run optimization loop
  useEffect(() => {
    if (!optimizationRunning || !autoOptimizeAlgorithm) return;

    const interval = setInterval(() => {
      if (autoOptimizeAlgorithm === 'all') {
        // Race all algorithms
        stepOptimization('bayesian');
        stepOptimization('cmaes');
        stepOptimization('gradient');
      } else {
        // Single algorithm
        stepOptimization(autoOptimizeAlgorithm);
      }
    }, 100); // Fast optimization

    return () => clearInterval(interval);
  }, [optimizationRunning, autoOptimizeAlgorithm, stepOptimization]);

  // Update convergence chart
  useEffect(() => {
    const maxIter = Math.max(
      algorithmProgress.bayesian?.iteration || 0,
      algorithmProgress.cmaes?.generation || 0,
      algorithmProgress.gradient?.iteration || 0
    );

    if (maxIter === 0) {
      setConvergenceData([]);
      return;
    }

    const data = [];
    for (let i = 0; i <= maxIter; i++) {
      const point = { iteration: i };

      // Bayesian
      if (algorithmProgress.bayesian && algorithmProgress.bayesian.observations.length > i) {
        const minLoss = Math.min(...algorithmProgress.bayesian.observations.slice(0, i + 1).map(o => o.loss));
        point.bayesian = minLoss;
      }

      // CMA-ES
      if (algorithmProgress.cmaes && i <= algorithmProgress.cmaes.generation) {
        point.cmaes = metrics.cmaesLoss;
      }

      // Gradient
      if (algorithmProgress.gradient && algorithmProgress.gradient.history.length > i) {
        const minLoss = Math.min(...algorithmProgress.gradient.history.slice(0, i + 1).map(h => h.loss));
        point.gradient = minLoss;
      }

      if (Object.keys(point).length > 1) {
        data.push(point);
      }
    }

    setConvergenceData(data);
  }, [algorithmProgress, metrics]);

  const handleStart = (algo) => {
    if (optimizationRunning) {
      stopOptimization();
    } else {
      startOptimization(algo);
    }
  };

  return (
    <div style={{
      background: '#0f0f0f',
      borderRadius: '8px',
      padding: '20px',
      border: '1px solid #222'
    }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '20px' }}>
        <h3 style={{ margin: 0, fontSize: '16px', color: '#fff' }}>
          🏁 Algorithm Race
        </h3>
        <button
          onClick={() => setShowGroundTruth(!showGroundTruth)}
          style={{
            background: showGroundTruth ? '#ff4444' : '#333',
            border: 'none',
            borderRadius: '4px',
            padding: '6px 12px',
            color: '#fff',
            fontSize: '11px',
            cursor: 'pointer'
          }}
        >
          {showGroundTruth ? '🙈 Hide Truth' : '👁️ Show Truth'}
        </button>
      </div>

      {/* Control buttons */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(2, 1fr)', gap: '12px', marginBottom: '20px' }}>
        <button
          onClick={() => handleStart('all')}
          style={{
            background: optimizationRunning && autoOptimizeAlgorithm === 'all' ? '#ff4444' : 'linear-gradient(135deg, #4488ff, #ff44ff)',
            border: 'none',
            borderRadius: '6px',
            padding: '14px',
            color: '#fff',
            fontWeight: 'bold',
            fontSize: '14px',
            cursor: 'pointer',
            transition: 'all 0.2s'
          }}
        >
          {optimizationRunning && autoOptimizeAlgorithm === 'all' ? '⏸ Stop Race' : '🚀 Race All'}
        </button>

        <button
          onClick={resetAllOptimizers}
          disabled={optimizationRunning}
          style={{
            background: '#333',
            border: '1px solid #444',
            borderRadius: '6px',
            padding: '14px',
            color: '#fff',
            fontWeight: 'bold',
            fontSize: '14px',
            cursor: optimizationRunning ? 'not-allowed' : 'pointer',
            opacity: optimizationRunning ? 0.5 : 1
          }}
        >
          ↺ Reset All
        </button>
      </div>

      {/* Individual algorithm controls */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: '12px', marginBottom: '20px' }}>
        <AlgorithmButton
          name="Bayesian Opt"
          algo="bayesian"
          color="#44ff88"
          running={optimizationRunning && (autoOptimizeAlgorithm === 'bayesian' || autoOptimizeAlgorithm === 'all')}
          onClick={() => handleStart('bayesian')}
        />
        <AlgorithmButton
          name="CMA-ES"
          algo="cmaes"
          color="#ff44ff"
          running={optimizationRunning && (autoOptimizeAlgorithm === 'cmaes' || autoOptimizeAlgorithm === 'all')}
          onClick={() => handleStart('cmaes')}
        />
        <AlgorithmButton
          name="Gradient"
          algo="gradient"
          color="#ffff44"
          running={optimizationRunning && (autoOptimizeAlgorithm === 'gradient' || autoOptimizeAlgorithm === 'all')}
          onClick={() => handleStart('gradient')}
        />
      </div>

      {/* Convergence chart */}
      {convergenceData.length > 0 && (
        <div style={{ marginBottom: '20px' }}>
          <h4 style={{ fontSize: '13px', color: '#aaa', marginBottom: '12px' }}>
            Loss Convergence
          </h4>
          <ResponsiveContainer width="100%" height={250}>
            <LineChart data={convergenceData}>
              <CartesianGrid strokeDasharray="3 3" stroke="#222" />
              <XAxis
                dataKey="iteration"
                stroke="#666"
                label={{ value: 'Iteration', position: 'insideBottom', offset: -5, fill: '#888' }}
              />
              <YAxis
                stroke="#666"
                scale="log"
                domain={['auto', 'auto']}
                label={{ value: 'Loss (log scale)', angle: -90, position: 'insideLeft', fill: '#888' }}
              />
              <Tooltip
                contentStyle={{
                  background: '#1a1a1a',
                  border: '1px solid #333',
                  borderRadius: '4px',
                  color: '#fff'
                }}
                formatter={(value) => value.toFixed(3)}
              />
              <Legend wrapperStyle={{ color: '#888' }} />

              {convergenceData.some(d => d.bayesian !== undefined) && (
                <Line
                  type="monotone"
                  dataKey="bayesian"
                  stroke="#44ff88"
                  strokeWidth={2}
                  dot={false}
                  name="Bayesian"
                />
              )}

              {convergenceData.some(d => d.cmaes !== undefined) && (
                <Line
                  type="monotone"
                  dataKey="cmaes"
                  stroke="#ff44ff"
                  strokeWidth={2}
                  dot={false}
                  name="CMA-ES"
                />
              )}

              {convergenceData.some(d => d.gradient !== undefined) && (
                <Line
                  type="monotone"
                  dataKey="gradient"
                  stroke="#ffff44"
                  strokeWidth={2}
                  dot={false}
                  name="Gradient"
                />
              )}
            </LineChart>
          </ResponsiveContainer>
        </div>
      )}

      {/* Algorithm status cards */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: '12px' }}>
        <AlgorithmStatus
          name="Bayesian Opt"
          progress={algorithmProgress.bayesian}
          color="#44ff88"
          groundTruthParams={showGroundTruth ? groundTruthParams : null}
        />
        <AlgorithmStatus
          name="CMA-ES"
          progress={algorithmProgress.cmaes}
          color="#ff44ff"
          groundTruthParams={showGroundTruth ? groundTruthParams : null}
        />
        <AlgorithmStatus
          name="Gradient"
          progress={algorithmProgress.gradient}
          color="#ffff44"
          groundTruthParams={showGroundTruth ? groundTruthParams : null}
        />
      </div>
    </div>
  );
}

function AlgorithmButton({ name, algo, color, running, onClick }) {
  return (
    <button
      onClick={onClick}
      style={{
        background: running ? '#ff4444' : '#1a1a1a',
        border: `2px solid ${running ? '#ff4444' : color}`,
        borderRadius: '6px',
        padding: '10px',
        color: '#fff',
        fontSize: '12px',
        fontWeight: 'bold',
        cursor: 'pointer',
        transition: 'all 0.2s',
        boxShadow: running ? `0 0 20px ${color}` : 'none'
      }}
    >
      {running ? '⏸' : '▶'} {name}
    </button>
  );
}

function AlgorithmStatus({ name, progress, color, groundTruthParams }) {
  if (!progress || !progress.bestParams) {
    return (
      <div style={{
        background: '#1a1a1a',
        border: '1px solid #222',
        borderRadius: '6px',
        padding: '12px'
      }}>
        <div style={{ fontSize: '12px', color, marginBottom: '8px', fontWeight: 'bold' }}>
          {name}
        </div>
        <div style={{ fontSize: '11px', color: '#666' }}>
          Not started
        </div>
      </div>
    );
  }

  const { bestParams, bestLoss } = progress;

  return (
    <div style={{
      background: '#1a1a1a',
      border: `1px solid ${color}`,
      borderRadius: '6px',
      padding: '12px',
      boxShadow: `0 0 15px ${color}33`
    }}>
      <div style={{ fontSize: '12px', color, marginBottom: '8px', fontWeight: 'bold' }}>
        {name}
      </div>

      <div style={{ fontSize: '10px', color: '#888', marginBottom: '4px' }}>
        Loss: <span style={{ color: '#fff', fontWeight: 'bold' }}>{bestLoss.toFixed(3)}</span>
      </div>

      <div style={{ fontSize: '9px', color: '#666', marginTop: '8px' }}>
        <div>K: {formatStiffness(bestParams.stiffness)}
          {groundTruthParams && ` (${formatStiffness(groundTruthParams.stiffness)})`}
        </div>
        <div>ζ: {bestParams.damping.toFixed(3)}
          {groundTruthParams && ` (${groundTruthParams.damping.toFixed(3)})`}
        </div>
        <div>μ: {bestParams.friction.toFixed(3)}
          {groundTruthParams && ` (${groundTruthParams.friction.toFixed(3)})`}
        </div>
      </div>
    </div>
  );
}

function formatStiffness(val) {
  if (val >= 1e6) return `${(val / 1e6).toFixed(1)}M`;
  if (val >= 1e3) return `${(val / 1e3).toFixed(0)}k`;
  return val.toFixed(0);
}
