import { Canvas } from '@react-three/fiber';
import { OrbitControls, PerspectiveCamera, Text, Box, Cylinder } from '@react-three/drei';
import { useEffect, useRef, useState } from 'react';
import * as THREE from 'three';

/**
 * 3D visualization of contact physics - shows connector insertion
 */
function InsertionScene({ position, contactForce, label, showForces }) {
  const connectorRef = useRef();
  const socketRef = useRef();

  useEffect(() => {
    if (connectorRef.current) {
      connectorRef.current.position.y = position;
    }
  }, [position]);

  // Visualize contact force with color intensity
  const forceIntensity = Math.min(1, contactForce / 100); // Normalize to 0-1
  const connectorColor = new THREE.Color().lerpColors(
    new THREE.Color(0x4444ff),
    new THREE.Color(0xff4444),
    forceIntensity
  );

  return (
    <>
      {/* Title */}
      <Text
        position={[0, 0.15, 0]}
        fontSize={0.015}
        color="#ffffff"
        anchorX="center"
        anchorY="middle"
      >
        {label}
      </Text>

      {/* Socket (female connector) */}
      <group ref={socketRef} position={[0, -0.02, 0]}>
        <Box args={[0.04, 0.04, 0.04]} position={[0, 0, 0]}>
          <meshStandardMaterial color="#333333" metalness={0.8} roughness={0.2} />
        </Box>
        {/* Insertion hole */}
        <Cylinder args={[0.008, 0.008, 0.025, 16]} position={[0, 0.0125, 0]}>
          <meshStandardMaterial color="#111111" metalness={0.9} roughness={0.1} />
        </Cylinder>
      </group>

      {/* Connector (male connector) */}
      <group ref={connectorRef}>
        {/* Connector body */}
        <Box args={[0.03, 0.02, 0.03]} position={[0, 0.01, 0]}>
          <meshStandardMaterial color={connectorColor} metalness={0.6} roughness={0.3} />
        </Box>
        {/* Pin */}
        <Cylinder args={[0.007, 0.007, 0.025, 16]} position={[0, -0.0125, 0]}>
          <meshStandardMaterial color={connectorColor} metalness={0.8} roughness={0.2} />
        </Cylinder>
      </group>

      {/* Force visualization */}
      {showForces && contactForce > 0.1 && (
        <group position={[0, position, 0]}>
          <primitive
            object={new THREE.ArrowHelper(
              new THREE.Vector3(0, -1, 0),
              new THREE.Vector3(0, 0, 0),
              0.03 * forceIntensity,
              0xff0000,
              0.005,
              0.003
            )}
          />
        </group>
      )}

      {/* Contact point indicator */}
      {contactForce > 0.1 && (
        <mesh position={[0, -0.02, 0]}>
          <sphereGeometry args={[0.002, 16, 16]} />
          <meshBasicMaterial color="#ff0000" opacity={0.8} transparent />
        </mesh>
      )}
    </>
  );
}

/**
 * Main contact visualizer component with split view
 */
export default function ContactVisualizer({ groundTruthTrace, userSimResult, showComparison = true }) {
  const [animationTime, setAnimationTime] = useState(0);
  const [isPlaying, setIsPlaying] = useState(true);

  useEffect(() => {
    if (!isPlaying || !groundTruthTrace) return;

    const maxTime = groundTruthTrace.forceTrace[groundTruthTrace.forceTrace.length - 1].time;
    const interval = setInterval(() => {
      setAnimationTime(t => {
        const next = t + 0.016; // ~60fps
        return next > maxTime ? 0 : next;
      });
    }, 16);

    return () => clearInterval(interval);
  }, [isPlaying, groundTruthTrace]);

  if (!groundTruthTrace) {
    return (
      <div style={{ width: '100%', height: '400px', background: '#111', borderRadius: '8px', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
        <div style={{ color: '#666' }}>Initializing simulation...</div>
      </div>
    );
  }

  // Interpolate current state
  const getStateAtTime = (trace, time) => {
    if (!trace || !trace.forceTrace) return { position: 0, force: 0 };

    for (let i = 0; i < trace.forceTrace.length - 1; i++) {
      const curr = trace.forceTrace[i];
      const next = trace.forceTrace[i + 1];

      if (time >= curr.time && time <= next.time) {
        const t = (time - curr.time) / (next.time - curr.time);
        const position = trace.positionTrace[i].position +
                        t * (trace.positionTrace[i + 1].position - trace.positionTrace[i].position);
        const force = curr.contact + t * (next.contact - curr.contact);
        return { position, force };
      }
    }

    return {
      position: trace.positionTrace[trace.positionTrace.length - 1].position,
      force: trace.forceTrace[trace.forceTrace.length - 1].contact
    };
  };

  const groundTruthState = getStateAtTime(groundTruthTrace, animationTime);
  const userSimState = userSimResult ? getStateAtTime(userSimResult, animationTime) : { position: 0, force: 0 };

  return (
    <div style={{ width: '100%', height: '400px', position: 'relative', background: '#0a0a0a', borderRadius: '8px', overflow: 'hidden' }}>
      <Canvas>
        <PerspectiveCamera makeDefault position={[0.15, 0.05, 0.15]} />
        <OrbitControls
          enablePan={false}
          enableZoom={true}
          minDistance={0.1}
          maxDistance={0.5}
          target={[0, 0, 0]}
        />

        {/* Lighting */}
        <ambientLight intensity={0.4} />
        <directionalLight position={[5, 5, 5]} intensity={0.8} castShadow />
        <directionalLight position={[-5, 3, -5]} intensity={0.3} />
        <pointLight position={[0, 0.1, 0]} intensity={0.5} color="#4488ff" />

        {/* Ground truth (left side) */}
        <group position={[-0.06, 0, 0]}>
          <InsertionScene
            position={groundTruthState.position}
            contactForce={groundTruthState.force}
            label="Real Hardware"
            showForces={true}
          />
        </group>

        {/* User simulation (right side) */}
        {showComparison && userSimResult && (
          <group position={[0.06, 0, 0]}>
            <InsertionScene
              position={userSimState.position}
              contactForce={userSimState.force}
              label="Your Simulation"
              showForces={true}
            />
          </group>
        )}

        {/* Divider */}
        {showComparison && (
          <mesh position={[0, 0, 0]} rotation={[0, 0, Math.PI / 2]}>
            <planeGeometry args={[0.15, 0.001]} />
            <meshBasicMaterial color="#333333" opacity={0.5} transparent />
          </mesh>
        )}

        {/* Grid */}
        <gridHelper args={[0.3, 10, '#222222', '#111111']} position={[0, -0.06, 0]} />
      </Canvas>

      {/* Playback controls */}
      <div style={{
        position: 'absolute',
        bottom: '10px',
        left: '50%',
        transform: 'translateX(-50%)',
        background: 'rgba(0,0,0,0.8)',
        padding: '8px 16px',
        borderRadius: '20px',
        display: 'flex',
        gap: '12px',
        alignItems: 'center',
        backdropFilter: 'blur(10px)'
      }}>
        <button
          onClick={() => setIsPlaying(!isPlaying)}
          style={{
            background: 'none',
            border: 'none',
            color: '#fff',
            cursor: 'pointer',
            fontSize: '18px',
            padding: '0 8px'
          }}
        >
          {isPlaying ? '⏸' : '▶'}
        </button>
        <div style={{ color: '#888', fontSize: '12px' }}>
          {animationTime.toFixed(2)}s / {groundTruthTrace.forceTrace[groundTruthTrace.forceTrace.length - 1].time.toFixed(2)}s
        </div>
        <button
          onClick={() => setAnimationTime(0)}
          style={{
            background: 'none',
            border: 'none',
            color: '#fff',
            cursor: 'pointer',
            fontSize: '14px',
            padding: '0 8px'
          }}
        >
          ↺
        </button>
      </div>

      {/* Force indicators */}
      <div style={{
        position: 'absolute',
        top: '10px',
        left: '10px',
        background: 'rgba(0,0,0,0.8)',
        padding: '12px',
        borderRadius: '8px',
        fontSize: '12px',
        backdropFilter: 'blur(10px)'
      }}>
        <div style={{ color: '#4488ff', marginBottom: '4px' }}>
          Real: {groundTruthState.force.toFixed(1)}N
        </div>
        {showComparison && userSimResult && (
          <div style={{ color: '#ff8844' }}>
            Sim: {userSimState.force.toFixed(1)}N
          </div>
        )}
        <div style={{ color: '#666', marginTop: '8px', fontSize: '10px' }}>
          Position: {groundTruthState.position.toFixed(4)}m
        </div>
      </div>
    </div>
  );
}
