/**
 * Global state management for contact parameter identification
 */

import { create } from 'zustand';
import { ContactSimulator } from '../physics/contactSimulator';
import { BayesianOptimizer } from '../algorithms/bayesianOptimization';
import { CMAESOptimizer } from '../algorithms/cmaes';
import { GradientOptimizer } from '../algorithms/gradientOptimizer';

const useSimulationStore = create((set, get) => ({
  // Simulator instance
  simulator: null,

  // Ground truth data
  groundTruthTrace: null,
  groundTruthParams: null,
  trajectory: null,

  // User's manual parameters
  userParams: {
    stiffness: 5e5,
    damping: 0.3,
    friction: 0.45
  },

  // Current simulation results
  userSimResult: null,

  // Optimizers
  optimizers: {
    bayesian: null,
    cmaes: null,
    gradient: null
  },

  // Optimization state
  optimizationRunning: false,
  autoOptimizeAlgorithm: null, // 'bayesian', 'cmaes', 'gradient', or 'all'

  // Algorithm progress
  algorithmProgress: {
    bayesian: null,
    cmaes: null,
    gradient: null
  },

  // Performance metrics
  metrics: {
    userLoss: Infinity,
    bayesianLoss: Infinity,
    cmaesLoss: Infinity,
    gradientLoss: Infinity
  },

  // Validation results
  validationResults: null,
  validationRunning: false,

  // UI state
  selectedAlgorithm: 'manual',
  compareMode: false,

  // Parameter bounds
  bounds: {
    stiffness: [1e3, 1e7],
    damping: [0.01, 1.0],
    friction: [0.1, 0.9]
  },

  /**
   * Initialize simulation with ground truth
   */
  initializeSimulation: () => {
    const groundTruthParams = {
      stiffness: 5e5,
      damping: 0.3,
      friction: 0.45
    };

    const simulator = new ContactSimulator(groundTruthParams);

    // Generate simple insertion trajectory
    const trajectory = [
      { time: 0, position: 0 },
      { time: 0.8, position: 0.025 }
    ];

    // Generate ground truth data
    const groundTruthTrace = simulator.generateGroundTruthData(trajectory, 0.02);

    // Initialize optimizers
    const bounds = get().bounds;
    const bayesian = new BayesianOptimizer(bounds, simulator, groundTruthTrace, trajectory);
    const cmaes = new CMAESOptimizer(bounds, simulator, groundTruthTrace, trajectory);
    const gradient = new GradientOptimizer(bounds, simulator, groundTruthTrace, trajectory);

    set({
      simulator,
      groundTruthTrace,
      groundTruthParams,
      trajectory,
      optimizers: { bayesian, cmaes, gradient }
    });

    // Run initial user simulation
    get().updateUserSimulation();
  },

  /**
   * Update user's manual parameters
   */
  setUserParams: (params) => {
    set({ userParams: params });
    get().updateUserSimulation();
  },

  /**
   * Update simulation with current user parameters
   */
  updateUserSimulation: () => {
    const { simulator, userParams, groundTruthTrace, trajectory } = get();
    if (!simulator) return;

    const userSimResult = simulator.simulate(userParams, trajectory, groundTruthTrace.forceTrace.length);
    const userLoss = simulator.computeLoss(userParams, groundTruthTrace, trajectory);

    set({
      userSimResult,
      metrics: { ...get().metrics, userLoss }
    });
  },

  /**
   * Run one step of auto-optimization
   */
  stepOptimization: (algorithm) => {
    const { optimizers, simulator, groundTruthTrace } = get();
    if (!optimizers[algorithm]) return;

    const result = optimizers[algorithm].step();
    const progress = optimizers[algorithm].getProgress();

    set({
      algorithmProgress: {
        ...get().algorithmProgress,
        [algorithm]: progress
      },
      metrics: {
        ...get().metrics,
        [`${algorithm}Loss`]: progress.bestLoss
      }
    });

    return result;
  },

  /**
   * Start auto-optimization
   */
  startOptimization: (algorithm) => {
    set({
      optimizationRunning: true,
      autoOptimizeAlgorithm: algorithm
    });
  },

  /**
   * Stop auto-optimization
   */
  stopOptimization: () => {
    set({
      optimizationRunning: false,
      autoOptimizeAlgorithm: null
    });
  },

  /**
   * Reset optimizer
   */
  resetOptimizer: (algorithm) => {
    const { optimizers } = get();
    if (optimizers[algorithm]) {
      optimizers[algorithm].reset();
      set({
        algorithmProgress: {
          ...get().algorithmProgress,
          [algorithm]: null
        },
        metrics: {
          ...get().metrics,
          [`${algorithm}Loss`]: Infinity
        }
      });
    }
  },

  /**
   * Reset all optimizers
   */
  resetAllOptimizers: () => {
    const { optimizers } = get();
    Object.keys(optimizers).forEach(key => {
      if (optimizers[key]) {
        optimizers[key].reset();
      }
    });

    set({
      algorithmProgress: {
        bayesian: null,
        cmaes: null,
        gradient: null
      },
      metrics: {
        userLoss: get().metrics.userLoss,
        bayesianLoss: Infinity,
        cmaesLoss: Infinity,
        gradientLoss: Infinity
      }
    });
  },

  /**
   * Run validation on test cases
   */
  runValidation: async () => {
    set({ validationRunning: true });

    const { simulator, userParams, algorithmProgress } = get();
    const testTrajectories = ContactSimulator.generateTestTrajectories();

    const results = {
      user: [],
      bayesian: [],
      cmaes: [],
      gradient: []
    };

    // Test user parameters
    for (const traj of testTrajectories) {
      const result = simulator.simulate(userParams, traj.points);
      results.user.push({
        name: traj.name,
        success: result.success,
        finalPenetration: result.finalPenetration
      });
    }

    // Test algorithm results
    for (const [algName, progress] of Object.entries(algorithmProgress)) {
      if (progress && progress.bestParams) {
        for (const traj of testTrajectories) {
          const result = simulator.simulate(progress.bestParams, traj.points);
          results[algName].push({
            name: traj.name,
            success: result.success,
            finalPenetration: result.finalPenetration
          });
        }
      }
    }

    // Compute success rates
    const successRates = {};
    for (const [key, testResults] of Object.entries(results)) {
      if (testResults.length > 0) {
        successRates[key] = testResults.filter(r => r.success).length / testResults.length;
      }
    }

    set({
      validationResults: { results, successRates },
      validationRunning: false
    });
  },

  /**
   * Set selected algorithm for display
   */
  setSelectedAlgorithm: (algorithm) => {
    set({ selectedAlgorithm: algorithm });
  },

  /**
   * Toggle compare mode
   */
  toggleCompareMode: () => {
    set({ compareMode: !get().compareMode });
  }
}));

export default useSimulationStore;
