import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer, Cell } from 'recharts';
import useSimulationStore from '../store/simulationStore';

/**
 * Validation dashboard - test on held-out insertion tasks
 */
export default function ValidationDashboard() {
  const {
    validationResults,
    validationRunning,
    runValidation
  } = useSimulationStore();

  if (!validationResults) {
    return (
      <div style={{
        background: '#0f0f0f',
        borderRadius: '8px',
        padding: '20px',
        border: '1px solid #222',
        textAlign: 'center'
      }}>
        <h3 style={{ margin: '0 0 16px 0', fontSize: '16px', color: '#fff' }}>
          🎯 Validation Results
        </h3>

        <div style={{ color: '#888', marginBottom: '20px', fontSize: '14px' }}>
          Test your parameters on 5 different insertion trajectories
        </div>

        <button
          onClick={runValidation}
          disabled={validationRunning}
          style={{
            background: validationRunning ? '#666' : 'linear-gradient(135deg, #4488ff, #44ff88)',
            border: 'none',
            borderRadius: '6px',
            padding: '14px 28px',
            color: '#fff',
            fontWeight: 'bold',
            fontSize: '14px',
            cursor: validationRunning ? 'not-allowed' : 'pointer'
          }}
        >
          {validationRunning ? '⏳ Running Validation...' : '▶ Run Validation'}
        </button>
      </div>
    );
  }

  const { results, successRates } = validationResults;

  // Prepare data for chart
  const chartData = Object.keys(results).map(key => ({
    name: key === 'user' ? 'Your Params' : key.charAt(0).toUpperCase() + key.slice(1),
    successRate: (successRates[key] || 0) * 100,
    color: getColor(key)
  }));

  return (
    <div style={{
      background: '#0f0f0f',
      borderRadius: '8px',
      padding: '20px',
      border: '1px solid #222'
    }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '20px' }}>
        <h3 style={{ margin: 0, fontSize: '16px', color: '#fff' }}>
          🎯 Validation Results
        </h3>
        <button
          onClick={runValidation}
          disabled={validationRunning}
          style={{
            background: '#333',
            border: '1px solid #444',
            borderRadius: '4px',
            padding: '6px 12px',
            color: '#fff',
            fontSize: '11px',
            cursor: 'pointer'
          }}
        >
          ↺ Re-run
        </button>
      </div>

      {/* Success rate chart */}
      <ResponsiveContainer width="100%" height={250}>
        <BarChart data={chartData}>
          <CartesianGrid strokeDasharray="3 3" stroke="#222" />
          <XAxis dataKey="name" stroke="#666" />
          <YAxis
            stroke="#666"
            domain={[0, 100]}
            label={{ value: 'Success Rate (%)', angle: -90, position: 'insideLeft', fill: '#888' }}
          />
          <Tooltip
            contentStyle={{
              background: '#1a1a1a',
              border: '1px solid #333',
              borderRadius: '4px',
              color: '#fff'
            }}
            formatter={(value) => `${value.toFixed(1)}%`}
          />
          <Bar dataKey="successRate" name="Success Rate">
            {chartData.map((entry, index) => (
              <Cell key={`cell-${index}`} fill={entry.color} />
            ))}
          </Bar>
        </BarChart>
      </ResponsiveContainer>

      {/* Detailed results */}
      <div style={{ marginTop: '24px' }}>
        <h4 style={{ fontSize: '13px', color: '#aaa', marginBottom: '12px' }}>
          Test Case Details
        </h4>

        <div style={{
          display: 'grid',
          gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))',
          gap: '12px'
        }}>
          {Object.entries(results).map(([key, testResults]) => {
            if (testResults.length === 0) return null;

            return (
              <div
                key={key}
                style={{
                  background: '#1a1a1a',
                  border: '1px solid #222',
                  borderRadius: '6px',
                  padding: '12px'
                }}
              >
                <div style={{
                  fontSize: '12px',
                  color: getColor(key),
                  marginBottom: '8px',
                  fontWeight: 'bold'
                }}>
                  {key === 'user' ? 'Your Params' : key.charAt(0).toUpperCase() + key.slice(1)}
                </div>

                <div style={{ fontSize: '10px', color: '#888' }}>
                  {testResults.map((test, idx) => (
                    <div
                      key={idx}
                      style={{
                        display: 'flex',
                        justifyContent: 'space-between',
                        marginBottom: '4px',
                        padding: '4px',
                        background: test.success ? '#0a3a0a' : '#3a0a0a',
                        borderRadius: '3px'
                      }}
                    >
                      <span>{test.name}</span>
                      <span style={{ color: test.success ? '#44ff88' : '#ff4444' }}>
                        {test.success ? '✓' : '✗'}
                      </span>
                    </div>
                  ))}
                </div>

                <div style={{
                  marginTop: '8px',
                  fontSize: '14px',
                  color: '#fff',
                  textAlign: 'center',
                  fontWeight: 'bold'
                }}>
                  {testResults.filter(t => t.success).length} / {testResults.length}
                </div>
              </div>
            );
          })}
        </div>
      </div>

      {/* Interpretation */}
      <div style={{
        marginTop: '20px',
        padding: '12px',
        background: '#1a1a1a',
        borderRadius: '6px',
        border: '1px solid #222',
        fontSize: '11px',
        color: '#888'
      }}>
        <div style={{ color: '#aaa', marginBottom: '4px' }}>
          <strong>Transfer Learning Test:</strong>
        </div>
        Higher success rate = better generalization to unseen insertion tasks.
        Parameters that work well across diverse trajectories are more likely to transfer to real hardware.
      </div>
    </div>
  );
}

function getColor(key) {
  const colors = {
    user: '#ff8844',
    bayesian: '#44ff88',
    cmaes: '#ff44ff',
    gradient: '#ffff44'
  };
  return colors[key] || '#888';
}
